parCap = cap;
sxnc_property *properties;
int propLen = 0;
parCap = cap;
sxnc_environment *environ;
sxnc_processor *processor;

initSaxonc(&environ, &processor, &parameters, &properties, parCap, parCap);

Processor processor = new Processor(true);
XQueryCompiler qc = processor.newXQueryCompiler();
XQueryExecutable exp1 = qc.compile(
        "declare function local:t1($v1 as xs:integer, $v2 as xs:double*) { " +
        "   $v1 div sum($v2)" +
        "};" +
        "10");
final XQueryEvaluator ev = exp1.load();
XdmValue v1 = new XdmAtomicValue(14);
XdmValue v2 = new XdmAtomicValue(5).append(new XdmAtomicValue(2));
XdmValue result = ev.callFunction(
   new QName("http://www.w3.org/2005/xquery-local-functions", "t1"), new XdmValue[]{v1, v2});

